/** @param {NS} ns */
export async function main(ns) {
  const cheap = ns => {
    // Avoid expensive APIs; we will only use:
    // ns.scan, hasRootAccess, getServerRequiredHackingLevel, getServerMaxMoney, 
    // getServerMoneyAvailable, getServerSecurityLevel, getServerMinSecurityLevel,
    // getServerMaxRam, getServerUsedRam, getHackingLevel, weaken, grow, hack, sleep, tprint
  };

  const findTargets = async () => {
    const targets = [];
    const visited = new Set();
    const queue = ['home'];
    const playerHack = ns.getHackingLevel();

    while (queue.length > 0) {
      const server = queue.shift();
      if (visited.has(server)) continue;
      visited.add(server);

      const reqs = ns.getServerRequiredHackingLevel(server);
      const maxMoney = ns.getServerMaxMoney(server);
      const hasRoot = ns.hasRootAccess(server);

      if (hasRoot && reqs <= playerHack && maxMoney > 0) {
        targets.push({ name: server, maxMoney, reqs });
      }

      const neighbors = ns.scan(server);
      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) queue.push(neighbor);
      }
    }

    return targets.sort((a, b) => b.maxMoney - a.maxMoney)[0] || null;
  };

  let iteration = 0;
  while (true) {
    const target = await findTargets();

    if (!target) {
      ns.tprint('No valid target found, rescanning...');
      await ns.sleep(5000);
      continue;
    }

    ns.tprint(`Target: ${target.name} (max: ${ns.formatNumber(target.maxMoney)})`);

    let hackCount = 0;
    const maxRam = ns.getServerMaxRam('home');
    const scriptRam = ns.getScriptRam(ns.getRunningScript());
    const availRam = maxRam - ns.getServerUsedRam('home');

    while (true) {
      const current = ns.getServerMoneyAvailable(target.name);
      const max = ns.getServerMaxMoney(target.name);
      const sec = ns.getServerSecurityLevel(target.name);
      const minSec = ns.getServerMinSecurityLevel(target.name);
      const useRam = Math.max(1, Math.floor((availRam - scriptRam) / 2));

      if (sec > minSec + 5) {
        await ns.weaken(target.name);
      } else if (current < max * 0.8) {
        await ns.grow(target.name);
      } else {
        await ns.hack(target.name);
        hackCount++;
      }

      iteration++;
      if (iteration % 50 === 0) {
        ns.tprint(`Status: ${target.name} cash=${ns.formatNumber(current)}/${ns.formatNumber(max)} sec=${sec.toFixed(1)} hacks=${hackCount}`);
      }

      await ns.sleep(100);

      // Rescan every 200 iterations
      if (iteration % 200 === 0) break;
    }
  }
}

