export async function main(ns) {
  const target = 'n00dles';
  const ports = [];

  // Try to open ports if functions exist
  if (typeof ns.bruteSsh === 'function') { ns.bruteSsh(target); ports.push(1); }
  if (typeof ns.ftpcrack === 'function') { ns.ftpcrack(target); ports.push(1); }
  if (typeof ns.relaysmtp === 'function') { ns.relaysmtp(target); ports.push(1); }
  if (typeof ns.httpworm === 'function') { ns.httpworm(target); ports.push(1); }
  if (typeof ns.sqlinject === 'function') { ns.sqlinject(target); ports.push(1); }

  // Nuke if we have enough ports open
  const required = ns.getServerNumPortsRequired(target);
  if (ports.length >= required) {
    ns.nuke(target);
  }

  // Main farm loop
  while (true) {
    const root = ns.hasRootAccess(target);
    if (!root) {
      const req = ns.getServerNumPortsRequired(target);
      let opened = 0;
      if (typeof ns.bruteSsh === 'function') { try { ns.bruteSsh(target); opened++; } catch(e) {} }
      if (typeof ns.ftpcrack === 'function') { try { ns.ftpcrack(target); opened++; } catch(e) {} }
      if (typeof ns.relaysmtp === 'function') { try { ns.relaysmtp(target); opened++; } catch(e) {} }
      if (typeof ns.httpworm === 'function') { try { ns.httpworm(target); opened++; } catch(e) {} }
      if (typeof ns.sqlinject === 'function') { try { ns.sqlinject(target); opened++; } catch(e) {} }
      if (opened >= req) ns.nuke(target);
      await ns.sleep(1000);
      continue;
    }

    const lvl = ns.getHackingLevel();
    const req_lvl = ns.getServerRequiredHackingLevel(target);
    if (lvl < req_lvl) { await ns.sleep(100); continue; }

    const sec = ns.getServerSecurityLevel(target);
    const min_sec = ns.getServerMinSecurityLevel(target);
    const mon = ns.getServerMoneyAvailable(target);
    const max_mon = ns.getServerMaxMoney(target);

    if (sec > min_sec + 5) {
      await ns.weaken(target);
    } else if (mon < 0.9 * max_mon) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

